select a.*, s.* from api.application a join api.status s on s.id=a.status_id join api.company c on c.id=a.company_id where c.name like '%Бета%';
select * from api.limit_balance;
select * from api.contract;
select column_name from information_schema.columns where table_schema='api' and table_name='application';
